1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = { itemType: string; amount: number };
14	
15	export type ClaimStep = {
16	  op: "claim";
17	  policy: number;
18	  incident: { cause: string; damages: Damage[] };
19	};
20	
21	export type Step = QuoteStep | ClaimStep;
22	
23	export type Customer = { yearsWithMHPCO: number };
24	
25	export type Scenario = {
26	  customer: Customer;
27	  steps: Step[];
28	};
29	
30	export type ScenarioResults = {
31	  results: unknown[];
32	};
33	
34	const PROCESSING_FEE = 5;
35	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
36	const LOYALTY_DISCOUNT = 0.2;
37	const LOYALTY_YEARS = 2;
38	const FOLLOW_UP_DISCOUNT = 0.15;
39	
40	const BASE_PREMIUMS: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	
49	const INSURANCE_VALUES: Record<string, number> = {
50	  sword: 1000,
51	  amulet: 600,
52	  staff: 800,
53	  potion: 400,
54	  rune: 250,
55	  moonstone: 250,
56	};
57	
58	const DEDUCTIBLE = 100;
59	const CAP_MULTIPLE = 2;
60	const HALF_REIMBURSEMENT_LEVEL = 8;
61	const HALF_REIMBURSEMENT = 0.5;
62	const FULL_REIMBURSEMENT = 1;
63	const DRAGON_MATERIAL = "dragon";
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_BASE_PREMIUM = 60;
67	
68	const COMPONENT_TYPES = ["rune", "moonstone"];
69	
70	/** Items are priced per type, because the component block applies to alike items. */
71	const groupByType = (items: Item[]): Map<string, Item[]> =>
72	  items.reduce(
73	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
74	    new Map<string, Item[]>(),
75	  );
76	
77	/**
78	 * Tallies how often each type occurs. Distinct from `groupByType`: pricing needs
79	 * the items themselves (material, enchantment, block size), whereas comparing a
80	 * claim against a policy needs only how many of a type each side names.
81	 */
82	const countByType = (types: string[]): Map<string, number> =>
83	  types.reduce(
84	    (counts, type) => counts.set(type, (counts.get(type) ?? 0) + 1),
85	    new Map<string, number>(),
86	  );
87	
88	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
89	
90	/**
91	 * Item-level risk surcharges, each a rate on the item's own base premium.
92	 * They are separate addends: unlike the policy-level initial assessment, they
93	 * do not compound with each other or with it.
94	 */
95	const CURSE_SURCHARGE = 0.5;
96	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
97	const HIGH_ENCHANTMENT_LEVEL = 5;
98	
99	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
100	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
101	  {
102	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
103	    rate: HIGH_ENCHANTMENT_SURCHARGE,
104	  },
105	];
106	
107	const itemSurchargeTotal = (item: Item): number =>
108	  ITEM_SURCHARGE_RULES.filter(({ applies }) => applies(item)).reduce(
109	    (sum, { rate }) => sum + itemBasePremium(item) * rate,
110	    0,
111	  );
112	
113	/**
114	 * A building block of exactly 3 alike components is offered at a special base
115	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
116	 * runes are charged per item.
117	 */
118	const formsComponentBlock = (type: string, items: Item[]): boolean =>
119	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
120	
121	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
122	  formsComponentBlock(type, items)
123	    ? BLOCK_BASE_PREMIUM
124	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
125	
126	const policyBasePremium = (items: Item[]): number =>
127	  [...groupByType(items)].reduce(
128	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
129	    0,
130	  );
131	
132	/**
133	 * Money is always rounded in the MHPCO's favour. Which way that is depends on
134	 * the direction it flows: a premium is paid *to* the MHPCO, so it rounds up;
135	 * a payout is paid *by* it, so it rounds down (see `roundPayoutInMHPCOsFavour`).
136	 */
137	const roundPremiumInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
138	
139	/**
140	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
141	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
142	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
143	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
144	 */
145	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
146	
147	const policyItemSurchargeTotal = (items: Item[]): number =>
148	  items.reduce((sum, item) => sum + itemSurchargeTotal(item), 0);
149	
150	/**
151	 * Policy-level modifiers, each a signed rate on the policy base premium.
152	 * Like the item-level surcharges they are independent addends: they do not
153	 * compound with one another. A discount is simply a negative rate.
154	 */
155	type Policy = { items: Item[]; paidOut: number };
156	
157	type ScenarioState = {
158	  customer: Customer;
159	  contractsIssued: number;
160	  policies: Map<number, Policy>;
161	};
162	
163	const POLICY_MODIFIER_RULES: { applies: (state: ScenarioState) => boolean; rate: number }[] = [
164	  {
165	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
166	    rate: -LOYALTY_DISCOUNT,
167	  },
168	  { applies: ({ contractsIssued }) => contractsIssued > 0, rate: -FOLLOW_UP_DISCOUNT },
169	];
170	
171	const policyModifierTotal = (basePremium: number, state: ScenarioState): number =>
172	  POLICY_MODIFIER_RULES.filter(({ applies }) => applies(state)).reduce(
173	    (sum, { rate }) => sum + basePremium * rate,
174	    0,
175	  );
176	
177	/**
178	 * The premium is the policy base premium plus a set of independent addends,
179	 * each a rate on that same base — they do not compound with one another:
180	 *
181	 *   100 base + 50 curse + 30 high ench - 20 loyalty + 10 first insurance = 170, + 5 fee
182	 *
183	 * The initial assessment surcharge is expressed via `withSurcharge` (base plus
184	 * its own rate) rather than as a bare addend, to keep the IEEE-754 behaviour
185	 * documented there.
186	 */
187	const premiumFor = (items: Item[], state: ScenarioState): number => {
188	  const basePremium = policyBasePremium(items);
189	  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
190	  const itemSurcharges = policyItemSurchargeTotal(items);
191	  const policyModifiers = policyModifierTotal(basePremium, state);
192	
193	  return roundPremiumInMHPCOsFavour(
194	    assessedPremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
195	  );
196	};
197	
198	/** The payout half of the rule on `roundPremiumInMHPCOsFavour`: down. */
199	const roundPayoutInMHPCOsFavour = (payout: number): number => Math.floor(payout);
200	
201	const insuranceSum = (items: Item[]): number =>
202	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
203	
204	/**
205	 * Reimbursement clauses, in precedence order: the first one that applies wins.
206	 * Unlike the premium's surcharges these are alternatives, not addends — a
207	 * dragon-material item enchanted to 9 is reimbursed at 50 %, not at 150 %.
208	 *
209	 * The dragon-material clause is written out even though it currently yields the
210	 * same rate as the default. It is a distinct rule of the domain — the spec calls
211	 * it "the only clause that applies" for an unenchanted dragon item, rather than
212	 * calling it no clause at all — and it merely *coincides* with the default
213	 * today. Naming it is what makes the precedence above visible: without it there
214	 * is nothing for the half-reimbursement clause to win against.
215	 */
216	const REIMBURSEMENT_CLAUSES: { applies: (item: Item) => boolean; rate: number }[] = [
217	  {
218	    applies: (item) => (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL,
219	    rate: HALF_REIMBURSEMENT,
220	  },
221	  { applies: (item) => item.material === DRAGON_MATERIAL, rate: FULL_REIMBURSEMENT },
222	];
223	
224	const reimbursementRate = (item: Item): number =>
225	  REIMBURSEMENT_CLAUSES.find(({ applies }) => applies(item))?.rate ?? FULL_REIMBURSEMENT;
226	
227	/**
228	 * The clause applies to the damage amount; the deductible is subtracted
229	 * afterwards, per damage event — i.e. once per damaged item.
230	 */
231	const reimbursedAmount = (item: Item, amount: number): number =>
232	  amount * reimbursementRate(item);
233	
234	const damagePayout = (damage: Damage, policy: Policy): number => {
235	  const item = policy.items.find(({ type }) => type === damage.itemType) as Item;
236	
237	  return reimbursedAmount(item, damage.amount) - DEDUCTIBLE;
238	};
239	
240	/**
241	 * A claim names the policy it is made against by the step index of the quote
242	 * that created it. That the policy exists is currently an *assumption*, not a
243	 * guarantee — a claim naming an unissued policy is a specified error case that
244	 * is not implemented yet, so this deliberately still fails on `undefined`.
245	 * The assumption is named here so that the missing check is visible rather
246	 * than buried in an `as` cast.
247	 */
248	const assumeIssued = (policy: Policy | undefined): Policy => policy as Policy;
249	
250	/**
251	 * Steps are processed in order and later steps depend on earlier ones — a quote
252	 * issues a contract that discounts every following quote, and a claim is made
253	 * against a policy an earlier quote created. Every operation therefore has the
254	 * same shape: it maps the state it is given to the result it reports and the
255	 * state the next step sees. Neither operation is a pure calculation, and
256	 * `runStep` below does not need to know which parts of the state each touches.
257	 */
258	type Outcome = { result: unknown; nextState: ScenarioState };
259	
260	/** A policy is filed under the index of the quote step that issued it. */
261	const withPolicy = (state: ScenarioState, at: number, policy: Policy): ScenarioState => ({
262	  ...state,
263	  policies: new Map(state.policies).set(at, policy),
264	});
265	
266	/** The MHPCO insures only what its price list names. */
267	const rejectUnknownItems = (items: Item[]): void => {
268	  items.forEach(({ type }) => {
269	    if (!(type in BASE_PREMIUMS)) {
270	      throw new Error(`the MHPCO price list does not cover a ${type}`);
271	    }
272	  });
273	};
274	
275	/** Issuing a contract discounts every quote that follows it. */
276	const quote = (step: QuoteStep, state: ScenarioState, index: number): Outcome => {
277	  rejectUnknownItems(step.items);
278	
279	  return {
280	    result: { premium: premiumFor(step.items, state) },
281	    nextState: withPolicy(
282	      { ...state, contractsIssued: state.contractsIssued + 1 },
283	      index,
284	      { items: step.items, paidOut: 0 },
285	    ),
286	  };
287	};
288	
289	/**
290	 * A damage entry names an insured item by type, and each entry is a separate
291	 * damage event. More entries of a type than the policy covers cannot all refer
292	 * to insured items, so the whole claim is rejected.
293	 */
294	const rejectUninsuredDamages = (damages: Damage[], policy: Policy): void => {
295	  const insured = countByType(policy.items.map(({ type }) => type));
296	
297	  countByType(damages.map(({ itemType }) => itemType)).forEach((claimed, type) => {
298	    const covered = insured.get(type) ?? 0;
299	
300	    if (claimed > covered) {
301	      throw new Error(
302	        `claim covers ${claimed} ${type} damage(s) but the policy insures ${covered}`,
303	      );
304	    }
305	  });
306	};
307	
308	/** A damage event cannot restore value, so a negative amount is not a claim. */
309	const rejectNegativeDamages = (damages: Damage[]): void => {
310	  damages.forEach(({ itemType, amount }) => {
311	    if (amount < 0) {
312	      throw new Error(`claim reports ${amount} damage to a ${itemType}, but damage cannot be negative`);
313	    }
314	  });
315	};
316	
317	const claim = (step: ClaimStep, state: ScenarioState): Outcome => {
318	  const policy = assumeIssued(state.policies.get(step.policy));
319	  rejectNegativeDamages(step.incident.damages);
320	  rejectUninsuredDamages(step.incident.damages, policy);
321	
322	  const cap = CAP_MULTIPLE * insuranceSum(policy.items);
323	  const desiredPayout = roundPayoutInMHPCOsFavour(
324	    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage, policy), 0),
325	  );
326	  const payout = Math.min(desiredPayout, cap - policy.paidOut);
327	  const paidOut = policy.paidOut + payout;
328	
329	  return {
330	    result: { payout, remainingCap: cap - paidOut },
331	    nextState: withPolicy(state, step.policy, { ...policy, paidOut }),
332	  };
333	};
334	
335	const runStep = (step: Step, state: ScenarioState, index: number): Outcome =>
336	  step.op === "quote" ? quote(step, state, index) : claim(step, state);
337	
338	export const runScenario = (scenario: Scenario): ScenarioResults => {
339	  const { results } = scenario.steps.reduce<{
340	    results: unknown[];
341	    state: ScenarioState;
342	  }>(
343	    ({ results, state }, step, index) => {
344	      const { result, nextState } = runStep(step, state, index);
345	
346	      return { results: [...results, result], state: nextState };
347	    },
348	    {
349	      results: [],
350	      state: { customer: scenario.customer, contractsIssued: 0, policies: new Map() },
351	    },
352	  );
353	
354	  return { results };
355	};
